insert into public.routes (slug,title,district_id,summary,duration_note,transport,best_time,budget_note,status,is_published,last_verified,direction,theme,sort_order) select 'south-viewpoints-sunset','Смотровые площадки юга и закат',(select id from public.districts where slug=null),'Поездка по южным смотровым: Karon Viewpoint с видом на три бухты, Windmill Viewpoint и пляж Най Харн. Финиш — закат у маяка на мысе Promthep.',null,'Между точками удобнее ехать на арендованной машине или такси/приложении такси (Grab, Bolt); на скутере — только с правами нужной категории и в шлеме.','Во второй половине дня, финиш — закат на Promthep Cape',null,'verified',false,date '2026-11-24','16plus','viewpoints',9;
