insert into public.route_stops (route_id,stop_order,place_id,note) select r.id,2,p.id,'Смотровая площадка с ветряной турбиной.' from public.routes r, public.places p where r.slug='south-viewpoints-sunset' and p.slug='windmill-viewpoint';
insert into public.route_stops (route_id,stop_order,place_id,note) select r.id,3,p.id,'Красивый пляж на юге среди холмов.' from public.routes r, public.places p where r.slug='south-viewpoints-sunset' and p.slug='nai-harn-beach';
insert into public.route_stops (route_id,stop_order,place_id,note) select r.id,4,p.id,'Южная оконечность с маяком и святилищем.' from public.routes r, public.places p where r.slug='south-viewpoints-sunset' and p.slug='promthep-cape';
insert into public.routes (slug,title,district_id,summary,duration_note,transport,best_time,budget_note,status,is_published,last_verified,direction,theme,sort_order) select 'west-coast-beaches','Пляжи западного побережья',(select id from public.districts where slug=null),'Поездка вдоль западного побережья с севера Патонга: Камала, смотровая Laem Singh, Сурин, Банг Тао и тихий Лаян у национального парка. Пляжи разные: от оживлённых до спокойных.',null,'Между точками удобнее ехать на арендованной машине или такси/приложении такси (Grab, Bolt); на скутере — только с правами нужной категории и в шлеме.','Днём; закат — на Laem Singh или Layan',null,'verified',false,date '2026-11-24','16plus','beaches',10;
insert into public.route_stops (route_id,stop_order,place_id,note) select r.id,1,p.id,'Главный пляж с длинной бухтой.' from public.routes r, public.places p where r.slug='west-coast-beaches' and p.slug='patong-beach';
insert into public.route_stops (route_id,stop_order,place_id,note) select r.id,2,p.id,'Тихий пляж среди зеленых холмов.' from public.routes r, public.places p where r.slug='west-coast-beaches' and p.slug='kamala-beach';
insert into public.route_stops (route_id,stop_order,place_id,note) select r.id,3,p.id,'Придорожная смотровая площадка на море.' from public.routes r, public.places p where r.slug='west-coast-beaches' and p.slug='laem-singh-viewpoint';
insert into public.route_stops (route_id,stop_order,place_id,note) select r.id,4,p.id,'Песчаный пляж в престижном районе.' from public.routes r, public.places p where r.slug='west-coast-beaches' and p.slug='surin-beach';
insert into public.route_stops (route_id,stop_order,place_id,note) select r.id,5,p.id,'Длинный песчаный пляж на побережье.' from public.routes r, public.places p where r.slug='west-coast-beaches' and p.slug='bang-tao-beach';
insert into public.route_stops (route_id,stop_order,place_id,note) select r.id,6,p.id,'Небольшой тихий пляж у парка.' from public.routes r, public.places p where r.slug='west-coast-beaches' and p.slug='layan-beach';
